plugins {
    id("common-configuration")
    id("com.autonomousapps.dependency-analysis")
    kotlin("jvm")
}

description = "Standalone Runner for Swift Import"

kotlin {
    explicitApi()
}

jvmToolchains {
    jdkVersion = JdkMajorVersion.JDK_25_0
    targetBytecodeVersion = JdkMajorVersion.JDK_25_0
}

dependencies {
    compileOnly(kotlinStdlib())

    api(project(":native:swift:kir"))
    api(project(":native:swift:sir"))
    implementation(project(":native:swift:kir-providers"))
    implementation(project(":native:swift:kir-light-classes"))
    // Bridges are generated by Swift Export's `SirBridgeProviderImpl`, which requires a (fake) Analysis API session.
    implementation(project(":native:swift:sir-providers"))
    implementation(project(":native:native.config"))
    implementation(project(":analysis:analysis-api"))
    implementation(project(":analysis:analysis-api-standalone"))
    implementation(project(":libraries:tools:analysis-api-based-klib-reader"))
    compileOnly(project(":kotlin-util-klib-metadata"))
    implementation(variantOf(libs.swiftextract) { classifier("osx-aarch_64") })
}

sourceSets {
    "main" { projectDefault() }
}

tasks.named("check") {
    dependsOn(":native:swift:swift-import-standalone-integration-tests:check")
}
